"""Corrections of the ebook text (proof-reading of books 11-15): applied by bk_extract.items(), so the typeset text, the
fidelity counts of bk_report and the font subsets all see the corrected text.

FIXES[scratch] = list of (part, old, new, note)
    part   part number (int) or '*' for every part of the book
    old    literal text (may run across inline runs of one paragraph) -- or re.compile(...) for a pattern
    new    replacement (a pattern's replacement may use \\1 ...)
    note   short reason, listed in docs/16k/corrections.md
A literal fix that matches nothing is reported by bk_report (fix_unused), so a fix can never silently go stale.
"""
import re

CJK = '㐀-䶿\u4e00-\u9fff'
_PUNCT = '，。、；：？！“”‘’（）《》〈〉「」『』…'
# A single em dash between two non-digit characters, one of them Chinese: the ebook's rendering of the Chinese dash '——'
# (ranges such as 1990—2000 or 19世纪—20世纪 keep the single dash; GB/T 15834 uses it as the connector).
DASH1 = re.compile(r'(?<=[%s%s])—(?![—\d])|(?<![—\d])—(?=[%s%s])' % (CJK, _PUNCT, CJK, _PUNCT))

# books whose cross-references point at <span id=…> anchors (captured as link targets)
SPAN_ANCHORS = {'q15': r'^jz_\d+_\d+$'}
SPECIAL = ('MOVE', 'RENUM', 'SHIFT', 'SPLIT', 'PGNO', 'RELINK', 'ADDMARK', 'NOTEBACK', 'HEAD', 'HREF', 'ANCHOR', 'PARA', 'CELL', 'JOIN')   # mark/structure fixes (not text replacements)

ASCII_COMMA = re.compile(r'(?<=[%s）”])\s?,\s?(?=[%s“（])' % (CJK, CJK))
ASCII_COLON = re.compile(r'(?<=[%s）])\s?:\s?(?=[%s“（])' % (CJK, CJK))

