        (9, '1812年，俄国也许应该彻底打败拿破仑军队，但俄国不如法国强大', '1812年，俄国彻底打败了拿破仑军队，但俄国并不比法国强大', '误译：Russia decisively defeated Napoleon'),
        (9, '当权力和结果难以辨别时，就更不用多说了', '当权力和结果难以辨别时，这一问题就无从谈起了', '误译：there is not much to say if power and outcomes are indistinguishable'),
        (9, '因为大规模的人口能产生大量的财富，是另一种形式的军事力量集聚', '因为只有大规模的人口才能产生大量的财富，而财富是军事力量的另一基石', '误译：the other building block of military power'),
