        (9, '那么这三个国家之间的潜在权力均势必然对中国不利', '那么必然会高估中国在这三个国家之间的潜在权力', '误译：农业比重高，国民生产总值会高估中国的潜在权力'),
        (9, '我改变1960年的指标有两个原因', '我在1960年改变指标有两个原因', '语序'),
        (9, '1806年，它被拿破仑军队击败，直到1813年，它被完全逐出欧洲均势圈', '1806年，它被拿破仑军队击败，此后直到1813年，它一直被完全排除在欧洲均势之外', '误译：直到1813年都被逐出均势之外'),
        (9, '滑铁卢战争后的100年间', '滑铁卢战役后的100年间', '用词：战役'),
        (9, '这说明了财富的改变如何引起人口的变化', '这说明了人口的变化如何引起财富的改变', '误译：因果颠倒'),
