        (9, '冷战期间形成的同盟模式表明，当财富与军事潜力持平时，这一问题就出现了。', '把财富与军事实力等同起来所存在的问题，在冷战期间形成的同盟模式中表现得很明显。', '误译：原意为等同财富与军事实力的问题见于冷战同盟模式'),
