        (10, '美国内战期间（1861—1865年），联盟军队封锁联邦军队可算得上是第九个例子', '美国内战期间（1861—1865年），联邦封锁南部邦联可算得上是第九个例子', '误译：Union 为联邦，Confederacy 为南部邦联'),
