        (10, '将军也只是在联邦陆军遭遇战争惨败后才投降的', '将军也只是在南部邦联陆军遭遇战争惨败后才投降的', '误译：联邦与南部邦联颠倒'),
        (10, '希特勒对英国发起了又一次舰艇战', '希特勒对英国发起了又一次潜艇战', '误译：U-boat campaign'),
        (10, '就是区别1945年8月和那关键一月的头两周发生了什么', '就是区别1945年8月之前和那关键一月的头两周分别发生了什么', '误译：漏「之前」'),
        (10, '唯一的重大险情是，日本是否可以避免', '唯一的重要问题是，日本是否可以避免', '误译：question'),
        (10, '日本的东线战场是它在西太平洋的本岛帝国', '日本的东线战场是它在西太平洋的岛屿帝国', '误译：island empire'),
        (10, '它击败了困守岛屿的大部分日军，并于1945年秋天发动对日本的进攻', '它击败了困守岛屿的大部分日军，并准备于1945年秋天进攻日本本土', '史实：进攻日本本土只是计划，并未实施'),
        (10, '通过谈判结束战争不可能使日本主权完好无缺', '通过谈判结束战争可以使日本主权完好无缺', '误译：逻辑相反（与下文「取得成功的关键」矛盾）'),
        (10, '苏联决定参加对日战争以及它第二天对满洲里关东军的进攻', '苏联决定参加对日战争以及它第二天对满洲的关东军的进攻', '地名：满洲（满洲里为城市名）'),
