        (10, '为在下方采取行动的友好的地面部队', '为在下方采取行动的友军地面部队', '误译：friendly ground forces 指友军'),
        (10, '“飞翔的炮兵” (flying artillery)', '“飞翔的炮兵”（flying artillery）', '括号统一'),
        (10, '战略轰炸可以通过处决敌人政治领导人的方式来确保战争的胜利', '战略轰炸可以通过“斩首”敌人政治领导层的方式来确保战争的胜利', '误译：decapitation 指斩首战略'),
        (10, '主张处决敌人领导人的观点认为', '主张“斩首”的观点认为', '误译：decapitation'),
        (10, '在考察历史记录之前，关于独立的空中能力的两个新观点是站得住脚的。', '在考察历史记录之前，有必要先就独立的空中能力说明两点。', '误译：two points are in order'),
        (10, '(5)20世纪60年代中期', '（5）20世纪60年代中期', '括号统一'),
        (10, '（7)20世纪80年代', '（7）20世纪80年代', '括号统一'),
        (10, '那么它在很大程度上也是依靠二战中所谓的轴心国（德国、意大利和日本）的联合轰炸', '那么它在很大程度上也是依靠二战中盟国对轴心国（德国、意大利和日本）的轰炸', '误译：轰炸者为盟国'),
        (10, '虽然德国在1942年底就明显就走向失败了', '虽然德国在1942年底就明显走向失败了', '多字：就'),
        (10, '严格地讲，盟军对意大利的轰炸开始于1943年7月', '盟军对意大利的大规模轰炸开始于1943年7月', '误译：began in earnest'),
        (10, '另外，1945年3月，美国海军的封锁摧垮了日本经济', '另外，到1945年3月，美国海军的封锁已摧垮了日本经济', '误译：by March 1945'),
        (10, '困在与对中国的一场无法打赢的战争中', '困在对中国的一场无法打赢的战争中', '多字：与'),
        (10, '希特勒并未感到内疚，也没有投降', '希特勒也没有因此被迫投降', '误译：did not feel compelled'),
        (10, '其中有五个例子并没有出现胁迫战略', '其中有五个例子的胁迫并未成功', '误译：coercion failed'),
        (10, '因为美国采用了谋杀战略', '因为美国采用了“斩首”战略', '误译：decapitation strategy'),
        (10, '但是，轰炸水坝并未毁坏北朝鲜的粮食作物，导致大面积饥荒', '但是，轰炸水坝并未毁坏北朝鲜的粮食作物，也没有导致大面积饥荒', '逻辑：漏否定'),
        (10, '那就是轰炸并没有使米洛舍维奇就范，单纯的轰炸', '那就是单靠轰炸并不能使米洛舍维奇就范，单纯的轰炸', '语义：与上下文一致'),
