        (10, '主要是德国在英国和大西洋水域向同盟国舰只发起进攻', '主要是德国在英国和大西洋水域向协约国舰只发起进攻', '史实：一战中英国一方为协约国'),
        (10, '最后，海军鱼雷布置于水下，使过往船只触雷爆炸', '最后，水雷布置于水下，使过往船只触雷爆炸', '误译：naval mines 指水雷'),
        (10, '1914—1918年间，战争勇士们放置了约24万枚水雷', '1914—1918年间，交战各方放置了约24万枚水雷', '误译：belligerents'),
