        (10, '拿破仑的战争机器深深陷人邻国西班牙', '拿破仑的战争机器深深陷入邻国西班牙', '错字：陷入'),
        (10, '这使英国部队能在友好的葡萄牙勇士控制下的海岸线登陆', '这使英国部队能在友好的葡萄牙军队控制下的海岸线登陆', '误译：forces'),
