        (10, '而另外一些如在冲绳的行动，则遭到了灭顶之灾，当时，入侵军队向内地进发时遭遇了日本的顽强抵抗', '而另外一些如在冲绳的行动，起初未遇抵抗，但入侵军队向内地进发时遭遇了日本的顽强抵抗，演变为血战', '误译：冲绳登陆最初未遇抵抗'),
        (10, '还有些如塔拉瓦岛、塞班岛和硫黄列岛', '还有些如塔拉瓦岛、塞班岛和硫黄岛', '地名：硫黄岛（Iwo Jima）'),
