        (10, '有效地消灭它们运行的政治实体', '有效地使它们不再作为运转的政治实体而存在', '误译：as functioning political entities'),
        (10, '不管哪一个国家如何渴望超越“相互确保摧毁”定则，建立核优势，核战争都不会在可以预见的将来爆发', '不管哪一个国家如何渴望超越“相互确保摧毁”定则，建立核优势，“相互确保摧毁”局面都会在可以预见的将来持续下去', '误译：MAD is likely to remain in place'),
