        (11, '1909年，奥地利在没有得到德国的任何怂恿下兼并了波斯尼亚', '1908年，奥地利在没有得到德国的任何怂恿下兼并了波斯尼亚', '史实：奥匈1908年兼并波斯尼亚'),
        (11, '事实上，在现代史上，国家寻求诱捕策略的例子就有好几个', '事实上，在现代史上，国家寻求诱捕策略的例子寥寥无几', '误译：few instances（下文仅举一例及一近似例）'),
        (11, '俄国凯瑟琳大帝', '俄国叶卡捷琳娜大帝', '人名通译'),
        (11, '的确，他们有自己迫切的理由与法国开战', '的确，它们有自己迫切的理由与法国开战', '代词'),
        (11, '坐观血腥厮杀是生存战略中一个更具前途的变种', '坐观血腥厮杀是诱捕战略的一个更具前途的变种', '误译：variant of bait and bleed'),
        (11, '这种方法可以让它们尽可能保持厮杀', '这样可以让它们尽可能多地互相残杀', '误译：let them kill as many as possible'),
        (11, '在我们建立一个单独的和平世界之际', '在我们单独媾和之际', '误译：separate peace'),
        (11, '只限于两极世界，因为这里没有潜在的大国联盟伙伴', '在两极世界中无法采用，因为这里没有潜在的大国联盟伙伴', '误译：not available in bipolar systems'),
        (11, '推卸责任是受威胁的大国在建立均势时的主要选择', '推卸责任是受威胁的大国除建立均势以外的主要选择', '误译：main alternative to balancing'),
        (11, '建立均势也不是推卸责任战略十分安全的选择', '建立均势也并非可以万无一失地替代推卸责任的选择', '误译：not a foolproof alternative'),
