        (11, 'DanReiter', 'Dan Reiter', '注释：缺空格'),
        (12, '德国和日本通过战争达到目的', '德国和日本试图通过战争达到这一目的', '误译：两国并未实现地区霸权'),
        (12, '但它似乎对获取相关权力不感兴趣', '但它似乎对获取相对权力不感兴趣', '误译：relative power'),
        (12, '因为实际上作为欧洲政治中的一个“角色”，很明显它是花时间“最少的一个大国”', '因为作为欧洲政治中的一个“角色”，它在大部分时间里显然是“大国中最弱小的一个”', '误译：the least of the great powers'),
        (12, '而应该用战争后方被误导的政策来解释', '而应该用国内被误导的政策来解释', '误译：domestic politics'),
        (12, '一个月内日本就站在同盟国一边加入了战争', '一个月内日本就站在协约国一边加入了战争', '史实：日本加入协约国一方'),
        (12, '在欧洲发生的两件关键的事情—1940年春天法国的沦陷', '在欧洲发生的两件关键的事情——1940年春天法国的沦陷', '标点：破折号'),
        (12, '而且，直截了当的权力算计是希特勒国际政治思想的中心', '但是，直截了当的权力算计也是希特勒国际政治思想的中心', '连词：转折'),
        ('*', '国际政治（Weltpolitik）', '世界政策（Weltpolitik）', '误译：Weltpolitik 通译世界政策'),
        (12, '在德国联邦下松散联系在一起的各个说德语的政治实体', '在德意志邦联下松散联系在一起的各个说德语的政治实体', '史实：German Confederation 通译德意志邦联'),
        (12, '俾斯麦摧毁了这个联邦', '俾斯麦摧毁了这个邦联', '同上'),
        (12, '不用挑起一场大国间的战争，德国的军队就已经征服了足够多的领土。如果真的挑起了一场大国间的战争，德国很可能会输。', '德国的军队已经征服了在不挑起一场大国间战争的前提下所能征服的几乎全部领土，而如果真的挑起了一场大国间的战争，德国很可能会输。', '误译：as much territory as it could without provoking a great-power war'),
        (12, '但是它并不是一个潜在的大国，因此它并不自信', '但是它并不是一个潜在的霸主，因此它并不自信', '误译：potential hegemon'),
        (12, '正如第二章中讨论的，潜在的大国在它的地区中拥有最强大的军队', '正如第二章中讨论的，潜在的霸主在它的地区中拥有最强大的军队', '误译：potential hegemon'),
        (12, '德国的军队比法国和普鲁士的军队都强大', '德国的军队比法国的军队强大', '错误：德国即由普鲁士统一而来，此处只比较德法'),
        (12, '他关于外交政策的观点比较乏味', '他关于外交政策的观点比较温和', '误译：moderate'),
        (12, '当托洛茨基1917年11月被任命为外交事务代表时', '当托洛茨基1917年11月被任命为外交人民委员时', '史实：职务名称'),
        (12, '列宁很快抓住了机会，红军进入华沙', '列宁很快抓住了机会，红军向华沙进军', '史实：红军未能进入华沙'),
        (12, '直到那时，双方都已被战争搞得精疲力竭', '到那时，双方都已被战争搞得精疲力竭', '用词'),
        (12, '但最后，在与第三帝国的战争中发生了彻底的改变，开始向西发动进攻，1943年初，已经到了柏林', '但最后，1943年初，与第三帝国的战争形势发生了彻底的改变，苏联开始向西朝柏林发动进攻', '史实：1943年初为战局转折，红军1945年才攻抵柏林'),
        (12, '于1938年，即意大利在二战中崩溃的四年前', '于1938年，即意大利在二战中崩溃的五年前', '计算：1938年至1943年为五年'),
        (12, '及威尼西亚（Ventia）', '及威尼西亚（Venetia）', '拼写'),
        (12, '1861年分裂并于1923年消亡的奥斯曼帝国', '1861年时已在走向解体、并于1923年消亡的奥斯曼帝国', '误译：奥斯曼帝国并非1861年分裂'),
        (12, '1866年，意大利投入兵力与普鲁士一起同匈牙利作战。普鲁士人在战场上粉碎了匈牙利人，但是意大利人被匈牙利人击败了', '1866年，意大利投入兵力与普鲁士一起同奥地利作战。普鲁士人在战场上粉碎了奥地利人，但是意大利人被奥地利人击败了', '史实：1866年对手为奥地利'),
        (12, '但是法国在1881年重创了意大利并夺取了突尼斯', '但是法国在1881年抢先一步夺取了突尼斯', '误译：beat Italy to the punch'),
        (12, '1895年，埃塞俄比亚的军队在阿杜瓦战役中', '1896年，埃塞俄比亚的军队在阿杜瓦战役中', '史实：阿杜瓦战役在1896年3月'),
        (12, '在著名的《伦敦和约》中，同盟军许诺意大利', '在著名的《伦敦条约》中，协约国许诺意大利', '史实：1915年《伦敦条约》由协约国与意大利签订'),
        (12, '意大利在这样一个适宜的时刻加入战争而获取了法国的领土和殖民地', '意大利在这样一个适宜的时刻加入战争，是为了获取法国的领土和殖民地', '误译：意大利并未获得（见下文）'),
        (12, '如果德国侵略英国的话，墨索里尼就会向纳粹德国提供军队', '墨索里尼表示，如果德国侵略英国的话，愿意向纳粹德国提供军队', '误译：offered troops'),
        (12, '有一个更加诡辩的作为退路的立场', '有一个更加精致的作为退路的立场', '误译：sophisticated'),
        (12, '唐吉诃德式的野心', '堂吉诃德式的野心', '人名通译'),
        (12, '因此，它犯了包围孤立政策的错误', '因此，它招致了对自身的包围', '误译：brought encirclement upon itself'),
        (12, '不仅是德国由于包围孤立政策的原因而不得不进行两线作战', '不仅是德国由于被包围而不得不进行两线作战', '误译：encirclement'),
        (12, '对付这一海军军备竞赛的最好方法是轻而易举地取胜', '对付这一海军军备竞赛的最好方法是在造舰上压倒德国', '误译：outbuild Germany'),
        (12, '所以它们与法俄结盟来维持均势并遏制德国', '所以他们与法俄结盟来维持均势并遏制德国', '代词'),
        (12, '希特勒一点也不专注于他的外交和宣传技巧', '希特勒不遗余力地运用他的外交和宣传技巧', '误译：语义相反'),
        (12, '与此同时，美国在1941年12月加入了战争，随后是英国，并且最后在西部开辟了第二战场', '与此同时，美国在1941年12月加入了战争，并与英国一道最终在西部开辟了第二战场', '史实：英国1939年即已参战'),
        (12, '尽管东京本来可以使英国在1940年7月和10月之间关闭缅甸通道，使荷兰为日本提供额外的原油', '尽管东京已经迫使英国在1940年7月至10月间关闭了滇缅公路，并迫使荷兰为日本提供额外的原油', '史实：滇缅公路确曾于1940年7—10月关闭'),
        (12, '不仅德国和日本在三国《同盟条约》中结盟', '不仅德国和日本在《三国同盟条约》中结盟', '书名号位置'),
        (12, '一个在两个不一致选择之间进行的持续的、痛苦的争论', '一个在两个都难以接受的选择之间进行的持续的、痛苦的争论', '误译：unpalatable alternatives'),
        (12, '由防御性现实主义者仔细识别的相反的命题', '与防御性现实主义者密切相关的相反命题', '误译：closely identified with'),
        (12, '针对德国进行战略性原子轰炸的“延伸”', '针对德国进行战略轰炸的“延伸”', '史实：二战中未对德国使用原子弹'),
        (12, '为了在苏联小型核武器降落地面之前消除它', '为了在地面上就摧毁苏联规模不大的核武库', '误译：destroy on the ground'),
        (12, '因为他在一篇关于核战争的文章中要求美国首先攻击并解除苏联的武装', '因为一旦发生核战争，他打算让美国首先攻击并解除苏联的武装', '误译：原意为他打算先发制人'),
        (12, '而且作为冷战的遗产，他们投入大量的资源', '而且在冷战余下的时间里，他们投入大量的资源', '误译：for the remainder of the Cold War'),
        (12, '例如，1962年12月，当SIOP-62（第一个SIOP）被批准时', '例如，1960年12月，当SIOP-62（第一个SIOP）被批准时', '史实：SIOP-62于1960年12月批准（下文「23年后」为1983年）'),
        (12, '在冷战的遗产中有四个重要的SIOP继承者', '在冷战余下的时间里有四个重要的SIOP继承者', '误译：for the remainder of the Cold War'),
        (12, '否则，它就不会获得相对于苏联的有价值的优势。', '但这并不是说它获得了相对于苏联的有价值的优势。', '误译：逻辑颠倒'),
        (12, '一些专家相信美国不具有对苏联的“漂亮的第一次打击”', '一些专家相信美国具有对苏联的“漂亮的第一次打击”', '误译：逻辑相反（作者不同意该评价）'),
        (12, '我不同意这种评价，但是有个小问题，在冷战的早期', '我不同意这种评价，但毫无疑问，在冷战的早期', '误译：there is little doubt'),
        (12, '虽然美国的政策制定者从来就没有确保摧毁的逻辑', '虽然美国的政策制定者从来就没有接受确保摧毁的逻辑', '漏字：接受'),
        (12, '而且，持续的军备竞赛并未被引入歧途', '而且，持续的军备竞赛并非误入歧途', '误译：was not misguided'),
        (12, '事实上，它给了苏联和美国一个很好的战略感觉在核王国中进行有力的竞争', '事实上，苏联和美国在核领域进行有力的竞争，在战略上是很有道理的', '误译：made good strategic sense'),
        (12, '然而，这些例子支持着我的观点', '而且，这些例子支持着我的观点', '连词误用'),
        (12, '寻求相对于其对手优势的事实表明了这样一种观点，即这些都是由于国内的病态导致的', '寻求相对于其对手优势的事实削弱了这样一种观点，即这些都是由于国内的病态导致的', '误译：逻辑相反'),
