        (13, '主要因为国会反对接纳视蓄奴制为合法的佛罗里达为美国的一个州', '主要因为国会反对接纳视蓄奴制为合法的得克萨斯为美国的一个州', '史实：所指为得克萨斯'),
        (13, '美国的领土增长了64%，即1 200万平方英里', '美国的领土增长了64%，即120万平方英里', '数字：120万平方英里'),
        (13, '但至19世纪40年后期', '但至19世纪40年代后期', '漏字：代'),
        (13, '北方起初很害怕，但最终恢复过来', '北方起初屡遭挫折，但最终恢复过来', '误译：stumbled'),
        (13, '在19世纪下半叶笨拙的美国军队可以将土著人', '在19世纪下半叶规模不大的美国军队可以将土著人', '误译：small army'),
