        (13, '看起来它在日俄战争（1904—1905年）中沉重地击败了俄国', '毕竟，它在日俄战争（1904—1905年）中沉重地击败了俄国', '误译：语气'),
        (13, '因为日本的巨大野心并不能持久，它不是一个潜在的霸主', '因为日本尽管野心巨大，却不是一个潜在的霸主', '误译：despite its ambitions'),
        (13, '事实上，法国和新西兰的溃败使它们在东南亚的帝国', '事实上，法国和荷兰的溃败使它们在东南亚的帝国', '错字：荷兰（Netherlands）'),
