        (13, '而是因为担心俄国以牺牲土耳其为代价向里海地区扩张', '而是因为担心俄国以牺牲土耳其为代价向黑海地区扩张', '史实：克里米亚战争起因于俄国在黑海—近东方向的扩张'),
