        (14, '事实上，奥地利并没有承担责任', '事实上，是奥地利承担了责任', '误译：逻辑相反（与下文一致）'),
        (14, '拿破仑在1805年的凯旋部分是俄国推卸责任的结果，这是1815年之前的10年间唯一典型的推卸责任案例。俄国在1807—1812年将责任推给英国，', '拿破仑在1805年的凯旋部分是普鲁士推卸责任的结果。1815年之前的10年间，另一个典型的推卸责任案例是俄国在1807—1812年将责任推给英国，', '错误：1805年推卸责任者为普鲁士（见上文）'),
