        (14, '反对法国东部边界的不同德国政治实体', '毗邻法国东部边界的不同德国政治实体', '误译：bordering'),
        (14, '它于1792年9月20日在瓦尔米（Valmy）入侵普鲁士时赢得了一次令人晕眩的胜利', '它于1792年9月20日在瓦尔米（Valmy）对入侵的普鲁士军队赢得了一次令人晕眩的胜利', '史实：瓦尔米战役中入侵者为普鲁士'),
        (14, 'Treaty of Luneville', 'Treaty of Lunéville', '地名变音符'),
