        (14, 'Relative Backwardness,with Special Reference', 'Relative Backwardness, with Special Reference', '注释：缺空格'),
        (14, '他并未就部队经商一事进行彻底的改变', '他并未对所继承的军队进行彻底的改变', '误译'),
        (14, '在拿破仑于1805年末征服奥地利后，1813年前已无暇形成联盟了，当时所有法国的大国对手都在玩弄均势', '在拿破仑于1805年末征服奥地利后，直到1813年以前，法国的大国对手从来没有能够同时都参与制衡', '误译：there was no time before 1813 when all rivals could balance'),
        (14, '后两个大国都具有征服的价值', '后两个地区都具有征服的价值', '错误：意大利与第三德国并非大国'),
