        (14, '而且，这使得法国（与德国接壤）而非苏联可能不再承担责任', '而且，这使得承担责任的很可能是与德国接壤的法国，而非苏联', '误译：逻辑相反'),
        (14, '而威廉德国在1903年便获得了欧洲霸主的地位', '而威廉德国在1903年便获得了欧洲潜在霸主的地位', '误译：potential hegemon'),
        (14, '在1918年夏，他要求获得土耳其东部领土', '在1945年夏，他要求获得土耳其东部领土', '史实：1945年6月（见第六章）'),
        (14, '如果共产主义没有渗透到西欧（包括联合托管的德国地区），自然要建立', '为了防止共产主义渗透到西欧（包括联合托管的德国地区），就必须建立', '误译：条件颠倒'),
        (14, '没有任何事情比英美在西德的危机更能激怒克里姆林宫了', '没有任何事情比英美在西德的举措更能激怒克里姆林宫了', '误译：initiatives'),
        (14, '苏联通过封锁柏林墙，切断与德国西占领区相连接的道路与水路', '苏联通过封锁柏林，切断西柏林与德国西占领区相连接的道路与水路', '史实：柏林墙1961年才修建'),
        (14, '当普鲁士在八年战争期间赢得三次战争时', '当普鲁士在八年间赢得三场战争时', '误译：eight-year period'),
        (14, '根据我的理论，均势与地缘因素应该在解释这些例子中有所不同', '根据我的理论，权力分配与地缘因素应该能够解释这些例子中的差异', '误译：distribution of power'),
